//! 📖️ Original paid parent/member custody lends genuine Drawing artboard metadata to Layout.
use semio_framework_plugin::{ArtifactView,app::{MemberKeyRef,editor::read::ChildEditorRead,vector_read::{ChildVectorReadCursor,ChildVectorReadStamp,ChildVectorSourceCustody,ChildVectorAdmissionProvider,OriginalChildMemberLookup}}};
use semio_framework_io_ports::{ChildAdmissionRead,ChildAdmissionQualificationV1,OriginalChildVectorPreparation,VectorCanvas,erase_child_admission_source};
use semio_framework_value::{ValueError,ValueRefusalKind,RetirementDemand,RetainedCloneGrant,RetainedCloneProgress,retained_clone::RetainedCloneSource,retirement::{RetireOwned,RetirementCursor,RetirementStep}};
use semio_s_artifact_layout_layout_model::{snapshot::LayoutSnapshot,DrawingSourceAddress,drawing_member_at,drawing_read_at,drawing_read_demand,drawing_member::source::reference::LAYOUT_DRAWING_REFERENCE_LENDER};
use semio_s_artifact_draw_drawing_model::snapshot::DrawingSnapshot;
use semio_s_artifact_draw_drawing_editor::child_editor::DRAWING_CHILD_VECTOR_READ;
use store::os_store::snapshot_read::SnapshotRead;
struct PreparationOwner(OriginalChildVectorPreparation);
struct PreparationRetirement{owner:Option<OriginalChildVectorPreparation>}
impl RetireOwned for PreparationOwner{fn retirement(self)->Box<dyn RetirementCursor>{Box::new(PreparationRetirement{owner:Some(self.0)})}fn retirement_birth_bytes(&self)->Option<usize>{Some(std::mem::size_of::<PreparationRetirement>())}fn controlled_retirement_supported()->bool{true}}
impl RetirementCursor for PreparationRetirement{fn next_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{self.owner.as_ref().map_or(Ok(Default::default()),|owner|owner.close_demand(body))}fn close_step(&mut self,g:RetainedCloneGrant)->RetirementStep{let Some(owner)=self.owner.as_mut()else{return RetirementStep::Complete};owner.begin_close();match owner.close_step(g){Err(error)=>RetirementStep::Failure(error),Ok(step)=>{let p=step.progress();if owner.terminal_is_empty(){self.owner=None}RetirementStep::Progress(p)}}}fn terminal_is_empty(&self)->bool{self.owner.is_none()}fn terminal_release_bytes(&self)->Option<usize>{Some(std::mem::size_of::<Self>())}}
type ParentSource=RetainedCloneSource<LayoutSnapshot,SnapshotRead<LayoutSnapshot>>;
#[derive(semio_framework_value::RetireOwned)]struct Owners{lookup:Option<OriginalChildMemberLookup>,preparation:Option<PreparationOwner>,qualification:Option<ChildVectorReadCursor>,custody:ChildVectorSourceCustody<DrawingSnapshot>,parent:Option<ParentSource>,original:Option<SnapshotRead<LayoutSnapshot>>}
pub struct OriginalPageDrawingSource{external_read:bool,owners:Owners,source:DrawingSourceAddress,phase:u8,quote:RetirementDemand,stamp:Option<ChildVectorReadStamp>,canvas:Option<VectorCanvas>,last:RetainedCloneProgress}
impl RetireOwned for OriginalPageDrawingSource{fn retirement(self)->Box<dyn RetirementCursor>{self.owners.retirement()}fn retirement_birth_bytes(&self)->Option<usize>{self.owners.retirement_birth_bytes()}fn controlled_retirement_supported()->bool{true}}
fn invalid(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
fn left(g:RetainedCloneGrant,p:RetainedCloneProgress)->RetainedCloneGrant{RetainedCloneGrant{maximum_items:g.maximum_items.saturating_sub(p.copied_items),maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(p.copied_bytes),maximum_capacity_bytes:g.maximum_capacity_bytes.saturating_sub(p.retained_capacity_bytes),maximum_release_bytes:g.maximum_release_bytes.saturating_sub(p.released_bytes),..g}}
fn sum(a:RetirementDemand,b:RetirementDemand)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:a.copy_bytes.checked_add(b.copy_bytes).ok_or_else(||invalid("Artboard read quote overflow"))?,capacity_bytes:a.capacity_bytes.checked_add(b.capacity_bytes).ok_or_else(||invalid("Artboard capacity quote overflow"))?,release_bytes:a.release_bytes.checked_add(b.release_bytes).ok_or_else(||invalid("Artboard close quote overflow"))?,depth:a.depth.max(b.depth)})}
impl OriginalPageDrawingSource{
 const HEADER:usize=std::mem::size_of::<Self>()*2;
 pub fn new(source:DrawingSourceAddress)->Self{Self{external_read:false,owners:Owners{lookup:None,original:None,parent:None,qualification:None,custody:ChildVectorSourceCustody::new(),preparation:None},source,phase:0,quote:Default::default(),stamp:None,canvas:None,last:Default::default()}}
 pub fn from_original(source:DrawingSourceAddress,original:SnapshotRead<LayoutSnapshot>)->Self{let mut owner=Self::new(source);owner.owners.original=Some(original);owner.phase=1;owner.external_read=true;owner}
 pub fn needs_member_read(&self)->bool{(2..=6).contains(&self.phase)}
 pub fn source(&self)->DrawingSourceAddress{self.source}
 pub fn ready(&self)->bool{self.phase==7}
 pub fn canvas_at(&self,parent:&LayoutSnapshot,source:DrawingSourceAddress)->Result<Option<VectorCanvas>,ValueError>{let same=matches!((self.source,source),(DrawingSourceAddress::Document,DrawingSourceAddress::Document))||matches!((self.source,source),(DrawingSourceAddress::Page(a),DrawingSourceAddress::Page(b))if a==b);if !self.ready()||!same||self.original_parent()?.get()as*const _!=parent as*const _{return Err(invalid("Artboard metadata requires its original prepared parent and member"))}Ok(self.canvas)}
 pub fn canvas(&self)->Option<VectorCanvas>{self.ready().then_some(self.canvas).flatten()}
 pub fn last_receipt(&self)->RetainedCloneProgress{self.last}
 pub fn read_qualification(&self)->Result<&ChildVectorReadStamp,ValueError>{self.stamp.as_ref().filter(|_|self.ready()).ok_or_else(||invalid("Original Drawing read qualification is not ready"))}
 pub fn take_command_authority(&self,cursor:&mut semio_framework_plugin::app::vector_read::command::OriginalChildEditorCommandCursor,read:&ChildEditorRead<'_,DrawingSnapshot>,g:RetainedCloneGrant)->Result<Option<(semio_framework_plugin::app::vector_read::command::OriginalChildEditorCommandAuthority,RetainedCloneProgress)>,ValueError>{if !self.ready(){return Err(invalid("Original Drawing read custody is not ready"))}cursor.take_authority(&self.owners.custody,read,g)}
 pub fn original_child(&self)->Result<semio_framework_value::retained_clone::RetainedCloneRef<'_,DrawingSnapshot>,ValueError>{if !self.ready(){return Err(invalid("Original Drawing child source is not ready"))}self.owners.custody.source()}
 pub fn original_parent(&self)->Result<semio_framework_value::retained_clone::RetainedCloneRef<'_,LayoutSnapshot>,ValueError>{self.owners.parent.as_ref().ok_or_else(||invalid("Original artboard parent is absent"))?.try_borrow()}
 fn ordinal(&self)->usize{match self.source{DrawingSourceAddress::Document=>0,DrawingSourceAddress::Page(index)=>index+1}}
 fn parent_source(&self)->Result<semio_framework_io_ports::ChildAdmissionSource<'_>,ValueError>{Ok(erase_child_admission_source(self.owners.parent.as_ref().ok_or_else(||invalid("Original artboard parent source is absent"))?.try_borrow()?,0x4c41594f))}
 fn quoted_read(&self)->Result<ChildAdmissionRead<'_>,ValueError>{Ok(ChildAdmissionRead{source:self.owners.custody.opaque_source()?,admitter:DRAWING_CHILD_VECTOR_READ.admission,vector:DRAWING_CHILD_VECTOR_READ.vector})}
 fn fixed(&self)->RetirementDemand{RetirementDemand{copy_bytes:Self::HEADER,depth:1,..Default::default()}}
 pub fn demand(&self,body:usize)->Result<RetirementDemand,ValueError>{let child=match self.phase{0|7=>RetirementDemand{depth:1,..Default::default()},1=>{let d=ParentSource::borrowed_constructor_demand::<SnapshotRead<LayoutSnapshot>>();RetirementDemand{capacity_bytes:d.capacity_bytes,depth:d.depth,..Default::default()}},2=>ChildVectorReadCursor::birth_demand(),3=>self.quote,4=>self.owners.custody.next_admit_demand()?,5=>OriginalChildVectorPreparation::birth_demand(),6=>{let own=Self::HEADER+ChildVectorAdmissionProvider::<DrawingSnapshot>::demand().copy_bytes+drawing_read_demand().copy_bytes;let d=self.owners.preparation.as_ref().unwrap().0.next_demand(&self.quoted_read()?,body.saturating_sub(own))?;sum(sum(ChildVectorAdmissionProvider::<DrawingSnapshot>::demand(),drawing_read_demand())?,d)?},_=>return Err(invalid("Original artboard read phase is invalid"))};let child=if !self.external_read&&self.needs_member_read(){if let Some(lookup)=self.owners.lookup.as_ref(){sum(lookup.demand::<DrawingSnapshot>(),child)?}else{OriginalChildMemberLookup::birth_demand()}}else{child};let mut d=sum(self.fixed(),child)?;d.depth=d.depth.saturating_add(1);Ok(d)}

 fn add(&mut self,p:RetainedCloneProgress){self.last.copied_items=self.last.copied_items.saturating_add(p.copied_items);self.last.copied_bytes=self.last.copied_bytes.saturating_add(p.copied_bytes);self.last.retained_capacity_bytes=self.last.retained_capacity_bytes.saturating_add(p.retained_capacity_bytes);self.last.released_bytes=self.last.released_bytes.saturating_add(p.released_bytes)}
 pub fn advance(&mut self,doc:&ArtifactView<'_,LayoutSnapshot>,g:RetainedCloneGrant)->Result<bool,ValueError>{
  self.last=Default::default();let demand=self.demand(g.maximum_copy_bytes)?;let minimum=if self.needs_member_read()&&self.owners.lookup.is_some(){if self.phase==6{4}else{2}}else{1};if g.maximum_items<minimum||!semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(false)}self.last.copied_bytes=Self::HEADER;let mut child=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-Self::HEADER,maximum_depth:g.maximum_depth-1,..g};
  let result=(||{if self.needs_member_read(){
   if self.owners.lookup.is_none(){let(lookup,p)=OriginalChildMemberLookup::admit(child)?;self.owners.lookup=Some(lookup);self.add(p);return Ok(false)}
   let parent=self.owners.parent.as_ref().ok_or_else(||invalid("Original artboard parent is absent"))?.try_borrow()?;if parent.get()as*const _!=doc.snapshot as*const _{return Err(invalid("Original artboard parent changed"))}let member=drawing_member_at(parent.get(),self.source)?.ok_or_else(||invalid("Original artboard member is absent"))?;
   let key=MemberKeyRef::root(if matches!(self.source,DrawingSourceAddress::Document){"backgroundDrawing"}else{"pages"},&member.handle.child_id);let step=DRAWING_CHILD_VECTOR_READ.read_original_render(parent,doc,key,self.owners.lookup.as_mut().unwrap(),child)?;child=left(child,step.progress);self.add(step.progress);let Some(read)=step.read else{return Ok(false)};self.step(None,doc.snapshot,Some(&read),child)
  }else{self.step(Some(doc),doc.snapshot,None,child)}})();
  if let Err(error)=result{self.add(error.retained_progress());self.last.copied_items=self.last.copied_items.max(1);return Err(error.with_retained_progress(self.last))}self.last.copied_items=self.last.copied_items.max(1);result
 }

 pub fn advance_original(&mut self,parent:&LayoutSnapshot,read:Option<&ChildEditorRead<'_,DrawingSnapshot>>,g:RetainedCloneGrant)->Result<bool,ValueError>{self.last=Default::default();let demand=self.demand(g.maximum_copy_bytes)?;if g.maximum_items<if self.phase==6{3}else{1}||!semio_framework_value::retained_clone::retained_clone_grant_admits(g,demand){return Ok(false)}self.last.copied_bytes=Self::HEADER;let child=RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-Self::HEADER,maximum_depth:g.maximum_depth-1,..g};let result=self.step(None,parent,read,child);if let Err(error)=result{self.add(error.retained_progress());self.last.copied_items=self.last.copied_items.max(1);return Err(error.with_retained_progress(self.last))}self.last.copied_items=self.last.copied_items.max(1);result}
 fn step(&mut self,doc:Option<&ArtifactView<'_,LayoutSnapshot>>,parent:&LayoutSnapshot,provided:Option<&ChildEditorRead<'_,DrawingSnapshot>>,g:RetainedCloneGrant)->Result<bool,ValueError>{if self.phase==0{self.owners.original=Some(doc.ok_or_else(||invalid("Artboard original parent read has not transferred"))?.take_snapshot_read().map_err(|_|invalid("Artboard read requires its actual original parent Store lease"))?);self.phase=1;return Ok(false)}if self.phase==1{let original=self.owners.original.take().unwrap();match original.admit_retained_clone_source(g){Ok((source,p))=>{self.owners.parent=Some(source);self.add(p);let parent=self.owners.parent.as_ref().unwrap().borrow();self.phase=if drawing_member_at(parent.get(),self.source)?.is_some(){2}else{7}},Err((error,original))=>{self.owners.original=Some(original);return Err(error)}}return Ok(self.ready())}if self.phase==7{return Ok(true)}let read=provided.ok_or_else(||invalid("Artboard step requires its original qualified member loan"))?;if self.original_parent()?.get()as*const _!=parent as*const _{return Err(invalid("Original artboard parent changed"))}match self.phase{
 2=>{let(cursor,p)=ChildVectorReadCursor::admit(g)?;self.owners.qualification=Some(cursor);self.add(p);self.quote=self.owners.qualification.as_ref().unwrap().next_demand(self.parent_source()?,&LAYOUT_DRAWING_REFERENCE_LENDER,self.ordinal(),read,&DRAWING_CHILD_VECTOR_READ.identity)?;self.phase=3},
 3=>{let ordinal=self.ordinal();let parent=erase_child_admission_source(self.owners.parent.as_ref().unwrap().try_borrow()?,0x4c41594f);let step=DRAWING_CHILD_VECTOR_READ.qualify(parent,&LAYOUT_DRAWING_REFERENCE_LENDER,ordinal,read,self.owners.qualification.as_mut().unwrap(),g)?;self.add(step.progress);if let Some(stamp)=step.stamp{self.stamp=Some(stamp);self.phase=4}else{self.quote=self.owners.qualification.as_ref().unwrap().next_demand(self.parent_source()?,&LAYOUT_DRAWING_REFERENCE_LENDER,ordinal,read,&DRAWING_CHILD_VECTOR_READ.identity)?}},
 4=>{let step=DRAWING_CHILD_VECTOR_READ.admit_original_source(read,self.stamp.as_ref().unwrap(),&mut self.owners.custody,g)?;self.add(step.progress());if self.owners.custody.ready(){self.phase=5}},
 5=>{let(owner,p)=OriginalChildVectorPreparation::admit(g)?;self.owners.preparation=Some(PreparationOwner(owner));self.add(p);self.phase=6},
 6=>{let current=read.member_metadata();let stamp=self.stamp.as_ref().unwrap().child_admission_stamp();if stamp.parent_identity!=current.parent_identity||stamp.child_identity!=current.child_identity||stamp.parent_revision!=*current.parent_revision||stamp.child_revision!=*current.child_revision{return Err(invalid("Original artboard child revision changed"))}let ordinal=self.ordinal();let(provider,p)=DRAWING_CHILD_VECTOR_READ.admission_provider(&self.owners.custody,ordinal,g)?;let mut used=p;let routed=match drawing_read_at(parent,self.source,&provider,provider.address(),left(g,used)){Ok(step)=>step,Err(error)=>{drop(provider);self.add(used);return Err(error)}};used.copied_items+=routed.progress.copied_items;used.copied_bytes+=routed.progress.copied_bytes;used.retained_capacity_bytes+=routed.progress.retained_capacity_bytes;used.released_bytes+=routed.progress.released_bytes;let Some(read)=routed.read else{drop(provider);self.add(used);return Err(invalid("Original artboard routed read is absent"))};let next=self.owners.preparation.as_mut().unwrap().0.advance(&read,left(g,used));let step=match next{Ok(step)=>step,Err(error)=>{self.add(used);return Err(error)}};used.copied_items+=step.progress.copied_items;used.copied_bytes+=step.progress.copied_bytes;used.retained_capacity_bytes+=step.progress.retained_capacity_bytes;used.released_bytes+=step.progress.released_bytes;let canvas=step.graph.and_then(|graph|graph.canvas());let done=step.done;let error=step.error;self.add(used);if let Some(error)=error{return Err(invalid(error))}if done{self.canvas=canvas;self.phase=7}},
 7=>return Ok(true),_=>return Err(invalid("Artboard read source phase is invalid"))}Ok(self.ready())}
}
